INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 7, 'theory', 'Quiz: tuples, arrays, vectors');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 0, 'What happens on a[5] for an array of three elements, if the index is not known at build time?', '["0 is returned", "a random value from memory is returned", "a panic at run time: index out of bounds", "the element is created automatically"]', 2, 'Rust checks the bounds on every access. The safe alternative is a.get(5), which returns None.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 1, 'What is part of the type of the array [i32; 3]?', '["only i32", "the element type and the length 3", "only the length", "the way it is stored on the heap"]', 1, 'The length is part of the type: [i32; 3] and [i32; 4] are different types. For a vector the length is not part of the type.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 2, 'How do you get the last element of a vector v, which may not exist?', '["v[-1]", "v.last() — returns an Option", "v.end()", "v[v.len()]"]', 1, 'There are no negative indexes. last() returns Some(&x), or None for an empty vector.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 3, 'Why is it convenient for functions to take a parameter of type &[i32]?', '["to change the vector", "to make the loop run faster", "because only slices can be passed", "such a function accepts an array, a vector and part of a vector"]', 3, 'A slice is a reference to part of a sequence. &arr, &vec and &vec[1..] all fit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 7, 4, 'What is needed to call v.push(4)?', '["declare the vector as let mut v", "nothing: push always works", "the vector must be an array", "call v.clone()"]', 0, 'Modifying methods need a mutable vector: let mut v = vec![…];');
